function kNatural(k){return k&&(k.voice==="max"||k.voice==="nova")}
function kSpeak(text,o={}){const k=S.kids;if(!k||!text)return;if(!o.force&&(k.voice==="off"))return;if(kNatural(k)&&!o.seq){const id=kRecId(text,k.voice);if(id){kPlayRec([id],k.voice,()=>kSpeak(text,Object.assign({},o,{seq:1})));return}}else if(o.force&&k.voice==="off"&&typeof KVREC!=="undefined"&&!o.seq){const id=kRecId(text,"max");if(id){kPlayRec([id],"max",()=>kSpeak(text,Object.assign({},o,{seq:1})));return}}try{if(kAud){kAud.pause();kAud=null}}catch(_){}try{const b=KVOX.find(x=>x[0]===(k.voice||"max"))||KVOX[0];let p=b[3],r=b[4];if(o.read||b[0]==="off"){p=Math.min(1.5,Math.max(.6,p));r=Math.min(1.1,Math.max(.85,r));if(b[0]==="off"){p=1;r=1}}
  const u=new SpeechSynthesisUtterance(kClean(text));u.lang="en-US";const v=kPickVoice();if(v)u.voice=v;u.pitch=p;u.rate=o.rate||r;if(o.cancel!==false)speechSynthesis.cancel();speechSynthesis.speak(u)}catch(_){}}
function kLine(text,pri=1){if(!kPend||pri>=kPend.p)kPend={t:text,p:pri};clearTimeout(kLine.tm);kLine.tm=setTimeout(()=>{const x=kPend;kPend=null;if(x)kSpeak(x.t)},40)}
