/* hints: a tip plus two wrong answers taken away */
const KMH=["","Start at the bigger number and count up.","Add (or subtract) the tens first, then the ones.","Work in columns: ones, tens, hundreds. Carry or borrow when needed.","Skip count! For 5s: 5, 10, 15, 20…","Use a fact you know: 6 × 7 is 6 × 5 plus 6 × 2.","Division is backwards times: what times the small number makes the big one?","Split the big number into tens and ones, multiply each, then add.","Two steps: first find the total, then take away.","Divide by the bottom number, then multiply by the top number.","Multiply the top and bottom by the same number.","Split one number into tens and ones, multiply both parts, then add.","How many whole times does it fit? What's left over is the remainder.","Line up the decimal points, then add like normal numbers.","Area = length × width. Perimeter = add all four sides.","Parentheses first, then × and ÷, then + and −.","10% means divide by 10. 50% is half. 25% is a quarter.","Picture a number line. Going below zero gives negative numbers.","Do the opposite to get x alone: + becomes −, × becomes ÷.","A square is a number times itself. A square root goes backwards.","Undo the + or − first, then undo the ×.","a² + b² = c². Square both short sides, add, then find the square root.","Triangle area = base × height ÷ 2. Circle area = π × r × r.","2³ means 2 × 2 × 2. Multiplying the same base? Add the exponents.","25% off means pay 75%. For proportions, multiply both parts by the same number.","Put the x number into the rule and do the math in order."];
function kHintText(Q){const q=Q.q||"";if(Q.kind==="bee")return `It starts with "${Q.word[0].toUpperCase()}" and has ${Q.word.length} letters.`;
  if(Q.pic&&/clock/i.test(q))return "Short hand = hour. Long red hand = minutes; each number is 5 minutes.";if(/fraction/i.test(q))return "Count ALL the parts for the bottom number, then the shaded parts for the top.";if(/coordinates/i.test(q))return "Go across (x) first, then up or down (y).";
  if(Q.s==="math")return KMH[Math.min(25,Q.lv||1)]||KMH[1];if(/flag/i.test(q))return "Two wrong flags are gone. Think about the colors and symbols!";if(/glowing/i.test(q))return "Look at where it is: which side of the map, and what's next to it?";
  if(/planet/i.test(q))return "Order from the Sun: My Very Educated Mother Just Served Us Nachos.";if(/phase/i.test(q))return "Waxing = the light grows on the right. Waning = only the left side is lit.";if(/kind of animal|is a (mammal|insect|bird|reptile)/i.test(q))return "Mammals have fur and drink milk; insects have 6 legs; birds have feathers; reptiles have scales.";
  if(/spelled correctly/i.test(q))return "Say the word slowly and picture each sound.";if(/means the same/i.test(q))return "Put each choice in a sentence. Which keeps the same meaning?";if(/past tense/i.test(q))return "Say: Yesterday I ___. Many past-tense words end in -ed, but some are special.";if(/plural/i.test(q))return "Plural means more than one. Some words change inside, like mouse → mice.";
  if(/binary/i.test(q))return "Binary place values from the right: 1, 2, 4, 8, 16. Add the places that have a 1.";if(/repeat|loop/i.test(q))return "A loop repeats: multiply the times by the steps.";if(/pattern|comes next/i.test(q))return "Find the part that repeats, then keep it going.";if(Q.mono)return "Think of what the command's letters stand for.";
  if(/speed/i.test(q))return "Speed = distance ÷ time.";if(/capital/i.test(q))return "The capital is where the government meets. Two wrong answers are gone!";return "Two wrong answers are gone. You've got this!"}
function kUseHint(Q){if(!Q||Q.rm||Q.a<0&&Q.kind!=="bee")return;const k=KS();k.hints++;Q.hint=kHintText(Q);if(Q.kind==="bee")Q.rm=[];else Q.rm=kShuf([0,1,2,3].filter(i=>i!==Q.a)).slice(0,2);kSpeak(Q.hint,{read:true,force:true});kBeep("click");persist()}
