function kMineStart(){const k=KS(),P=kRoverPuzzle(k.mine.lvl);P.ob=P.g.map(row=>row.map(c=>c?kPick(k.mine.lvl>=3?["stone","stone","lava","leaf"]:["stone","stone","leaf"]):""));KV={scr:"mine",P}}
function kRoverSolve(P){const key=(x,y,d)=>x+","+y+","+d,prev=new Map([[key(P.sx,P.sy,P.d),null]]);let fr=[[P.sx,P.sy,P.d]],goal=null;
  while(fr.length&&!goal){const nx=[];for(const [x,y,d] of fr){if(x===P.tx&&y===P.ty){goal=[x,y,d];break}const mv=[["L",[x,y,(d+3)%4]],["R",[x,y,(d+1)%4]]],st=n=>{let cx=x,cy=y;for(let i=0;i<n;i++){cx+=KDIR[d][0];cy+=KDIR[d][1];if(cx<0||cy<0||cx>=P.N||cy>=P.N||P.g[cy][cx])return null}return[cx,cy,d]};
    const s1=st(1);if(s1)mv.push(["F",s1]);if(P.loop){const s3=st(3);if(s3)mv.push(["F3",s3])}for(const [c,m] of mv){const kk=key(...m);if(!prev.has(kk)){prev.set(kk,[key(x,y,d),c]);nx.push(m)}}}fr=nx}
  if(!goal)return{prog:[],cells:[]};const prog=[],cells=new Set();let kk=key(...goal);while(prev.get(kk)){const [pk,c]=prev.get(kk);prog.unshift(c);const [x,y]=kk.split(",");cells.add(x+","+y);kk=pk}return{prog,cells:[...cells]}}
function kRoverRun(){const P=KV.P;if(!P.prog.length)return;P.state="run";P.x=P.sx;P.y=P.sy;P.dd=P.d;P.path=[];const steps=[];for(const c of P.prog){if(c==="F3")steps.push("F","F","F");else steps.push(c)}
  let i=0;const tick=()=>{if(KV.scr!=="mine"||KV.P!==P)return;if(i>=steps.length){P.state=(P.x===P.tx&&P.y===P.ty)?"win":"miss";if(P.state==="miss")kLine("Almost there! Add more commands.",2);kMineEnd();renderKids();return}
    const s=steps[i++];if(s==="L")P.dd=(P.dd+3)%4;else if(s==="R")P.dd=(P.dd+1)%4;else{const nx=P.x+KDIR[P.dd][0],ny=P.y+KDIR[P.dd][1];if(nx<0||ny<0||nx>=P.N||ny>=P.N||P.g[ny][nx]){P.state="crash";kBeep("crash");kLine("Bonk! Fix your code and try again.",2);renderKids();return}P.path.push(P.x+","+P.y);P.x=nx;P.y=ny;if(P.x===P.tx&&P.y===P.ty){P.state="win";kMineEnd();renderKids();return}}
    kBeep("step");renderKids();setTimeout(tick,340)};setTimeout(tick,200)}
function kMineEnd(){const P=KV.P,k=KS();if(P.state!=="win"||P.scored)return;P.scored=1;const n=P.prog.length;P.stars=n<=P.best?3:n<=P.best+2?2:1;k.mine.solved++;
  if(P.hinted){P.stars=0;P.got="Solved with the route hint, so no diamonds this time. Try the next map on your own!";kBeep("ok");kLine("Map solved! Next time, try it without the hint.",3)}
  else{if(P.stars===3)k.mine.stars3++;const d=P.stars===3?2:1;k.mine.dia+=d;k.today.dia+=d;kGive("dia",d);kGive("stone",2);kGive("wood",1);k.xp+=15+5*P.stars+k.mine.lvl;k.coins+=P.stars;if(P.stars>=2&&k.mine.lvl<20)k.mine.lvl++;P.got=`+${d} 💎 diamond${d>1?"s":""}, +2 stone, +1 wood`;kAnswer("code",true);kBeep("chest");kFx=true;kLine("Diamond mined!",4);kRotDone("mine")}
  P.lab=kQ(kSubPick({sci:2,math:1.5,code:1,geo:1,eng:1}));P.labAns=null;kBadges();kUnlocks();persist()}
function kMineView(v){const P=KV.P,k=KS(),bio=KBIO[kLocIdx(k)];
  if(P.state==="win"&&P.lab){v.innerHTML=`<div class="kids">${kToastHtml()}${kTop("Block Miner","home")}<div class="kcard kend"><h2>💎 ${P.hinted?"Map solved!":"Diamond mined!"} ${"⭐".repeat(P.stars)}</h2><p><b>${esc(P.got)}</b></p><p>${P.prog.length} commands · best possible ${P.best}${P.stars&&P.stars<3?" · try for fewer commands next time":""}</p></div>
    <div class="kcard"><div class="kh">🔬 Bonus: answer to test the sample (+3 ⚡)</div></div>${k.lessonQ&&P.labAns==null?kLessonCard():kQuestion(P.lab,P.labAns,"mineNext")}</div>`;return}
  const route=P.hinted?P.route:[],cell=(x,y)=>{const r=P.x===x&&P.y===y,t=P.tx===x&&P.ty===y,ob=P.g[y][x],tr=(P.path||[]).includes(x+","+y),rt=route.includes(x+","+y);
    return r?`<span class="kc g" style="--bio:${bio}"><b class="krov" style="transform:rotate(${P.dd*90}deg)">▲</b></span>`:t?`<span class="kc bk bl-ore">✨</span>`:ob?`<span class="kc bk bl-${P.ob[y][x]}"></span>`:`<span class="kc g ${tr?"tr":""} ${rt?"route":""}" style="--bio:${bio}"></span>`};
  const grid=Array.from({length:P.N},(_,y)=>Array.from({length:P.N},(_,x)=>cell(x,y)).join("")).join(""),max=P.best+5,lab={F:"⬆",L:"↺",R:"↻",F3:"🔁3⬆"},off=P.prog.length>=max||P.state==="run";
  const msg=P.state==="crash"?"💥 Bonk! The bot hit a block or the edge. Fix your code and run it again.":P.state==="miss"?"🤔 The bot stopped before the diamond. Add more commands.":P.state==="run"?"Running your code…":P.hinted?"💡 The glowing squares show a route. (No diamonds when you use the hint.)":"Program the bot (▲ points the way it faces) to reach the diamond ore ✨, then press Run.";
  v.innerHTML=`<div class="kids">${kToastHtml()}${kTop("Block Miner","home")}<div class="kcard"><div class="kpad" style="justify-content:space-between"><b>Map level ${k.mine.lvl}</b><span class="ksmall">Best: ${P.best} commands</span>${!P.hinted&&P.state!=="run"?`<button class="kbtn ghost small" data-k="mhint">💡 Hint</button>`:""}</div><div class="kgrid" style="grid-template-columns:repeat(${P.N},1fr)">${grid}</div><div class="ksmall">${esc(msg)}</div></div>
   <div class="kcard"><div class="kprog">${P.prog.length?P.prog.map(c=>`<span class="kcmd">${lab[c]}</span>`).join(""):'<span class="ksmall">Your code appears here</span>'}</div>
    <div class="kpad"><button class="kbtn" data-kc="F" ${off?"disabled":""}>⬆ Forward</button><button class="kbtn" data-kc="L" ${off?"disabled":""}>↺ Left</button><button class="kbtn" data-kc="R" ${off?"disabled":""}>↻ Right</button>${P.loop?`<button class="kbtn" data-kc="F3" ${off?"disabled":""}>🔁 Repeat 3 × ⬆</button>`:""}</div>
    <div class="kpad"><button class="kbtn big green" data-k="run" ${!P.prog.length||P.state==="run"?"disabled":""}>▶ Run</button><button class="kbtn ghost" data-k="undo" ${P.state==="run"?"disabled":""}>⌫ Undo</button><button class="kbtn ghost" data-k="clear" ${P.state==="run"?"disabled":""}>Clear</button><button class="kbtn ghost" data-k="newmap" ${P.state==="run"?"disabled":""}>New map</button></div></div></div>`}
/* ---------- game 3: chess quest (5 steps: puzzle, question, puzzle, question, puzzle) ---------- */
function kChessStart(){KV={scr:"chess",step:0,pawn:0,need:5};kChessNext()}
function kChessNext(){const g=KV,k=KS();if(g.step%4!==3){g.P=kPuzzle(k.chess.lv);g.Q=null;const key="chess:"+g.P.type;if(!k.seen[key])k.lessonQ=key}else{g.Q=kQ(kSubPick());g.ans=null;g.P=null}}
const KGL={K:"♚",Q:"♛",R:"♜",B:"♝",N:"♞",P:"♟"};
function kBoard(P){const b=P.state==="play"?P.b:P.b2,last=P.last||[],hint=(P.tries>=2||P.hinted)&&P.state==="play"?P.ok[0][0]:-1;
  return `<div class="kboard">${b.map((p,i)=>{const r=i>>3,c=i&7,cls=["ksq",(r+c)%2?"d":"l"];if(i===P.sel)cls.push("sel");if(last.includes(i))cls.push("last");if(i===hint)cls.push("hint");if(P.state==="play"&&P.dots.includes(i))cls.push(p?"dot cap":"dot");
    return `<button class="${cls.join(" ")}" data-ksq="${i}" aria-label="${"abcdefgh"[c]}${8-r}${p?" "+(cWhite(p)?"white ":"black ")+KPN[p.toUpperCase()]:""}">${p?`<span class="${cWhite(p)?"wp":"bp"}">${KGL[p.toUpperCase()]}&#xFE0E;</span>`:""}${c===0?`<em class="krk1">${8-r}</em>`:""}${r===7?`<em class="kfl">${"abcdefgh"[c]}</em>`:""}</button>`}).join("")}</div>`}
function kChessView(v){const g=KV,k=KS(),P=g.P;
  const track=`<div class="kostabs"><button class="kostab on" data-k="chess">♞ Chess Quest</button><button class="kostab" data-k="chessbot">🤖 Robot Chess</button><button class="kostab" data-k="poker">🃏 Poker</button></div><div class="kcard"><div class="kh">♟️ Push your pawn to the end to make a queen!</div><div class="kptrack">${Array.from({length:g.need+1},(_,i)=>`<span class="${i<g.pawn?"on":""}">${i===g.pawn?"♙":i===g.need?"👑":""}</span>`).join("")}</div><div class="ksmall">Chess puzzles and questions take turns. Each right answer (without a hint) moves your pawn.</div></div>`;
  if(k.lessonQ&&((P&&P.state==="play")||(!P&&g.ans==null))){v.innerHTML=`<div class="kids">${kToastHtml()}${kTop("Chess Quest","home")}${track}${kLessonCard()}</div>`;return}
  if(!P){v.innerHTML=`<div class="kids">${kToastHtml()}${kTop("Chess Quest","home")}${track}${kQuestion(g.Q,g.ans,"cnext")}</div>`;return}
  const done=P.state!=="play",why=P.state==="won"?(P.hinted?"✅ Solved! (hint used, so no points)":P.tries<2?`✅ ${P.cheer||"Great move!"}`:"✅ You found it!"):P.state==="shown"?"Here's the answer. You'll get the next one!":"";
  v.innerHTML=`<div class="kids">${kToastHtml()}${kTop("Chess Quest","home")}${track}<div class="kq" style="--sc:#ff9f1c"><div class="kqh"><span class="ksub">♟️ Chess · Lv ${P.lv}</span><span class="klife">${!done&&!P.hinted?`<button class="kbtn ghost small" data-k="chint">💡 Hint</button>`:""}<button class="kbtn ghost small" data-k="say">🔊</button></span></div>
   <div class="kqt">${esc(P.prompt)}</div><div class="ksmall2">You play white. Tap a piece to see where it can go, then tap a square.</div>${kBoard(P)}
   ${P.hinted&&!done?`<div class="khint">💡 ${esc(P.tip)} The red square shows which piece to move.</div>`:""}
   ${P.msg&&!done?`<div class="kfb no"><b>${esc(P.msg)}</b>${P.tries>=2&&!P.hinted?"<div>💡 Hint: the red square shows which piece to move.</div>":""}</div>`:""}
   ${done?`<div class="kfb ${P.state==="won"?"ok":"no"}"><b>${why}</b><div>💡 ${esc(P.tip)}</div></div><button class="kbtn big" data-k="cnext">Next ▶</button>`:""}</div></div>`}
function kChessTap(i){const g=KV,P=g.P;if(!P||P.state!=="play")return;const p=P.b[i];
  if(p&&cWhite(p)){P.sel=i;P.dots=cMoves(P.b,true).filter(m=>m[0]===i).map(m=>m[1]);kBeep("click");return}
  if(P.sel!=null&&P.dots.includes(i)){if(P.ok.some(m=>m[0]===P.sel&&m[1]===i)){P.b2=cMove(P.b,P.sel,i);P.last=[P.sel,i];P.state="won";kBeep("move");
      if(P.hinted){kChessHinted(P)}else{const ok=P.tries<(P.lv>=10?1:2);if(ok){g.pawn++;P.cheer=P.type==="mate"?"Checkmate!":P.type==="fork"?"Knight fork!":kPick(KCHEER)}kChessAnswer(P,ok);if(ok)kLine(P.type==="mate"?"Checkmate! Great move!":P.type==="fork"?"Knight fork! Nice!":kPick(KCHEER),2)}}
    else{P.tries++;P.msg=kChessWhy(P,P.sel,i);kBeep("no");kLine(P.tries>=2?"Not that one. Look at the red square for a hint.":"Not that one. Try again!",2);if(P.tries>=3){P.state="shown";P.last=P.ok[0];P.b2=cMove(P.b,P.ok[0][0],P.ok[0][1]);kChessAnswer(P,false)}}}
  P.sel=null;P.dots=[]}
function kChessHinted(P){const k=KS(),st=k.chess.st;st.n++;st.h.push(.5);if(st.h.length>12)st.h.shift();k.hints++;kLine("Solved! Next time, try it without the hint.",2);persist()}
function kChessAdvance(){const g=KV,k=KS();g.step++;if(g.pawn>=g.need){k.chess.promos++;k.coins+=30;k.xp+=50;kGive("gold",3);kBadges();kUnlocks();persist();kFx=true;kBeep("mate");kLine("Promotion! Your pawn is now a queen!",4);
    kTix(1,"promotion");kRotDone("chess");KV={scr:"reward",emoji:"👑",title:"Promotion!",lines:["Your pawn reached the end and became a QUEEN!","+30 ⚡ coins, +50 XP, 3 gold blocks and a 🎟️ Tesla Drive ticket"],again:"chess"};return}kChessNext()}
/* ---------- base builder ---------- */
function kBaseView(v){const k=KS(),sel=KV.sel||"grass",b=KBM[sel],un=sel==="erase"||kUnl(sel)||(k.inv[sel]||0)>0,n=k.inv[sel]||0;
  const pal=KBLK.filter(x=>kUnl(x[0])||(k.inv[x[0]]||0)>0||x[4]).map(x=>{const ok=kUnl(x[0])||(k.inv[x[0]]||0)>0;return `<button class="kpal ${sel===x[0]?"on":""} ${ok?"":"lock"}" data-kpal="${x[0]}" aria-label="${esc(x[1])}">${kCell(x[0])}<i>${ok?(k.inv[x[0]]||0):"🔒"}</i></button>`}).join("");
  const info=sel==="erase"?"Tap a block in your base to put it back in your bag.":!un?`🔒 ${b[1]}: ${b[5]} to unlock it.`:`${b[2]||""} ${b[1]}: ${n} in your bag.`;
  v.innerHTML=`<div class="kids">${kToastHtml()}${kTop(`My base on ${kLoc(k)}`,"home")}<div class="kbase" style="--bio:${KBIO[kLocIdx(k)]}">${k.base.map((id,i)=>kCell(id,"button",`data-kcell="${i}" aria-label="Square ${i+1}"`)).join("")}</div>
   <div class="kcard"><div class="kpals"><button class="kpal ${sel==="erase"?"on":""}" data-kpal="erase" aria-label="Remove blocks"><span class="kcell it">🧽</span></button>${pal}</div>
    <div class="ksmall">${esc(info)}</div>${sel!=="erase"&&un&&kUnl(sel)?`<button class="kbtn small" data-k="buy" ${k.coins<b[3]*5?"disabled":""}>Buy 5 for ${b[3]*5} ⚡</button>`:""}
    <div class="ksmall">Win blocks in every game, in quests and chests. New planets and achievements unlock new blocks!</div></div></div>`}
function kBaseTap(i){const k=KS(),sel=KV.sel||"grass",cur=k.base[i];
  if(sel==="erase"){if(cur){kGive(cur,1);k.base[i]="";kBeep("click")}persist();return}
  if(!(kUnl(sel)||(k.inv[sel]||0)>0))return;if((k.inv[sel]||0)<1){kT(`Out of ${KBM[sel][1]}. Buy more or win some in the games!`);return}
  if(cur===sel)return;if(cur)kGive(cur,1);k.base[i]=sel;k.inv[sel]--;k.placed++;k.today.place++;kBeep("place");kBadges();persist()}
function kRewardView(v){const g=KV;v.innerHTML=`<div class="kids">${kToastHtml()}${kTop(g.title,"home")}<div class="kcard kend"><div class="kbig2">${g.emoji}</div><h2>${esc(g.title)}</h2>${g.lines.map(l=>`<p>${esc(l)}</p>`).join("")}
  <div class="kpad">${g.again?`<button class="kbtn big" data-k="${g.again}">Play again ▶</button>`:""}<button class="kbtn ${g.again?"ghost":"big"}" data-k="home">${g.again?"Home":"Awesome!"}</button></div></div></div>`}
function kBadgesView(v){const k=KS();v.innerHTML=`<div class="kids">${kTop("Badges","home")}<div class="kbgrid">${KBAD.map(b=>`<div class="kbig ${k.badges[b[0]]?"on":""}"><span>${b[1]}</span><b>${esc(b[2])}</b><em>${esc(b[3])}</em></div>`).join("")}</div></div>`}
/* ---------- update ---------- */
function kUpdBtn(){return typeof updateReady!=="undefined"&&updateReady?`<button class="kupd" data-k="kupd">🆕 New update ready! Tap to update</button>`:""}
function kCheckUpd(){if(!navigator.onLine){kT("No internet right now. Try again later.");render();return}kT("Checking for updates…");render();
  fetch("./version.json?t="+Date.now(),{cache:"no-store"}).then(r=>r.ok?r.json():Promise.reject()).then(j=>{if(j&&j.v&&j.v!==BUILD){updateReady=j.v;kT("Updating to the newest version…");render();applyUpdate()}else{kT("✅ You have the newest version!");render()}}).catch(()=>{kT("Couldn't check right now. Try again later.");render()})}

