const kLHold={};document.addEventListener("pointerdown",e=>{try{if(view!=="kids"||KV.scr!=="land"||!kLnd)return;const b=e.target.closest&&e.target.closest(".lhold");if(!b)return;e.preventDefault();const m={lthr:"thr",lleft:"left",lright:"right"}[b.id];if(!m)return;kLnd[m]=true;kLHold[e.pointerId]=m;try{b.releasePointerCapture&&b.releasePointerCapture(e.pointerId)}catch(_){}kLastAct=Date.now()}catch(_){}});
["pointerup","pointercancel"].forEach(ev=>document.addEventListener(ev,e=>{if(!kLnd)return;const m=kLHold[e.pointerId];if(m){kLnd[m]=false;delete kLHold[e.pointerId]}},true));
