document.addEventListener("pointerdown",e=>{try{if(view!=="kids"||KV.scr!=="col"||KV.mode!=="ast"||!e.target||e.target.id!=="kast")return;const r=e.target.getBoundingClientRect(),sc=e.target.width/r.width;kAstHit((e.clientX-r.left)*sc,(e.clientY-r.top)*sc);kLastAct=Date.now()}catch(_){}});

const KMTIP=["Cities earn 15× rent. Building on land you own is often smarter than buying more land.","Keep some 💠 saved for rent, or you could go broke!","Research Labs give tech: every tech level makes ALL your rents 10% bigger.","Cheap regions near the start get landed on a lot. They can be great deals!","Net worth = cash + land + buildings. That's how the winner is decided.","Robo buys when it has extra money. Grab the best regions first!"];
/* ---------- Mars Empire: an easy board game (a Monopoly + Civilization mix) inside Mars Colony ---------- */
const KMB=[["start","🚀","Launch Pad"],["reg","🟤","Utopia Plain",60,6],["card","📡","Mission Card"],["reg","🔵","Polar Ice Cap",80,8],["reg","🟠","Arabia Terra",100,10],
 ["lab","🔬","Research Lab"],["reg","🟢","Elysium",120,12],["reg","🟣","Hellas Basin",140,14],["storm","🌪️","Dust Storm"],["reg","⚪","Gale Crater",160,16],["card","📡","Mission Card"],
 ["reg","🟡","Tharsis Ridge",180,18],["lab","🔬","Research Lab"],["reg","🔴","Valles Marineris",220,22],["reg","🌋","Olympus Mons",260,26],["reg","💎","Jezero Crater",300,30]];
const KMBUILD=["","🏕️ Outpost","🏠 Base","🏙️ City"],KMBMUL=[1,3,7,15];
function meNew(){const own={};KMB.forEach((s,i)=>{if(s[0]==="reg")own[i]={o:null,b:0}});KV={scr:"col",mode:"emp",E:{own,p:[{pos:0,cash:500,tech:0,name:"You",ic:"🧑‍🚀"},{pos:0,cash:500,tech:0,name:"Robo",ic:"🤖"}],turn:0,round:1,maxR:15,log:["Welcome to Mars Empire! Roll the dice to explore Mars."],stage:"roll",die:0,Q:null,over:false}};kLine("Mars Empire! Roll the dice!",2)}
function meRent(E,i){const s=KMB[i],o=E.own[i],owner=E.p[o.o];return Math.round(s[4]*KMBMUL[o.b]*(1+owner.tech*.1))}
function meWorth(E,pi){let w=E.p[pi].cash;for(const i in E.own){const o=E.own[i];if(o.o===pi)w+=KMB[i][3]+o.b*Math.round(KMB[i][3]*.6)}return w}
function meLog(E,t){E.log.push(t);if(E.log.length>6)E.log.shift()}
function meMove(E,pi,n){const P=E.p[pi],old=P.pos;P.pos=(P.pos+n)%KMB.length;if(P.pos<old){P.cash+=100;meLog(E,`${P.ic} ${P.name} passed the Launch Pad: +100 💠`)}return P.pos}
function meLand(E,pi){const P=E.p[pi],i=P.pos,s=KMB[i];
  if(s[0]==="reg"){const o=E.own[i];if(o.o===null){if(pi===0){E.stage="buy";return}if(P.cash>=s[3]+80){P.cash-=s[3];o.o=1;meLog(E,`🤖 Robo bought ${s[2]} for ${s[3]} 💠`)}return}
    if(o.o===pi){if(pi===0&&o.b<3){E.stage="build";return}if(pi===1&&o.b<3){const cost=Math.round(s[3]*.6);if(P.cash>=cost+60){P.cash-=cost;o.b++;meLog(E,`🤖 Robo built a ${KMBUILD[o.b].slice(3)} on ${s[2]}`)}}return}
    const rent=meRent(E,i),O=E.p[o.o];P.cash-=rent;O.cash+=rent;meLog(E,`${P.ic} ${P.name} paid ${rent} 💠 rent to ${O.name} (${s[4]} × ${KMBMUL[o.b]}${O.tech?` + ${O.tech*10}% tech`:""})`);if(pi===0){kBeep("no")}else kBeep("kaching");return}
  if(s[0]==="card"||s[0]==="lab"||s[0]==="storm"){if(pi===0){E.stage="q";E.qkind=s[0];E.Q=kQ(kSubPick());E.ans=null;return}
    if(s[0]==="card"){const g=kPick([40,60,80]);P.cash+=g;meLog(E,`🤖 Robo's mission card: +${g} 💠`)}else if(s[0]==="lab"){if(Math.random()<.6){P.tech++;meLog(E,`🤖 Robo researched new tech (Tech ${P.tech})`)}}else{P.cash-=30;meLog(E,"🌪️ Dust storm! Robo paid 30 💠 for repairs")}}}
function meRoll(){const E=KV.E;if(E.stage!=="roll"||E.over)return;const d=kR(1,6);E.die=d;kBeep("dice");meMove(E,0,d);meLog(E,`🎲 You rolled ${d} and landed on ${KMB[E.p[0].pos][2]}.`);meLand(E,0);if(E.stage==="roll")meRobo()}
function meRobo(){const E=KV.E;if(E.over)return;const d=kR(1,6);meMove(E,1,d);meLog(E,`🤖 Robo rolled ${d} → ${KMB[E.p[1].pos][2]}`);meLand(E,1);meEndRound()}
function meEndRound(){const E=KV.E;if(E.p.some(p=>p.cash<0)||E.round>=E.maxR){meFinish();return}E.round++;E.stage="roll";persist()}
function meAct(a){const E=KV.E,P=E.p[0],i=P.pos,s=KMB[i],k=KS();
  if(a==="buy"&&E.stage==="buy"){if(P.cash>=s[3]){P.cash-=s[3];E.own[i].o=0;meLog(E,`✅ You bought ${s[2]} for ${s[3]} 💠. Rent here: ${s[4]} 💠`);kBeep("kaching");kLine(`You bought ${s[2]}!`,1)}else meLog(E,"Not enough 💠 to buy it.");E.stage="roll";meRobo();return}
  if(a==="build"&&E.stage==="build"){const o=E.own[i],cost=Math.round(s[3]*.6);if(P.cash>=cost){P.cash-=cost;o.b++;meLog(E,`🏗️ You built a ${KMBUILD[o.b].slice(3)} on ${s[2]}! Rent is now ${meRent(E,i)} 💠`);kBeep("build")}else meLog(E,"Not enough 💠 to build.");E.stage="roll";meRobo();return}
  if(a==="skip"&&(E.stage==="buy"||E.stage==="build")){E.stage="roll";meRobo();return}}
function meAnswer(ok,Q){const E=KV.E,P=E.p[0];const hint=!!(Q&&Q.rm);kAnswer(Q.s,ok,Q);
  if(E.qkind==="card"){const g=ok&&!hint?kPick([60,80,100]):0;P.cash+=g;meLog(E,ok?(hint?"Right, but a hint means no bonus.":`📡 Mission success: +${g} 💠`):"📡 Mission failed. No bonus this time.")}
  else if(E.qkind==="lab"){if(ok&&!hint){P.tech++;meLog(E,`🔬 New tech! Tech level ${P.tech}: your rents are now +${P.tech*10}%`)}else meLog(E,"🔬 The experiment failed. Try again next lap!")}
  else{if(ok&&!hint)meLog(E,"🌪️ You knew it, so the dust storm missed you!");else{P.cash-=30;meLog(E,"🌪️ Dust storm damage: −30 💠")}}}
function meFinish(){const E=KV.E,k=KS();if(E.over)return;E.over=true;const a=meWorth(E,0),b=meWorth(E,1);E.win=a>b?"me":a<b?"bot":"tie";E.wa=a;E.wb=b;const t=E.win==="me"?2:1;kTix(t,E.win==="me"?"Mars Empire win":"Mars Empire game");kCol().cr+=Math.max(0,Math.round(a/10));
  k.emp=k.emp||{games:0,wins:0};k.emp.games++;if(E.win==="me"){k.emp.wins++;kFx=true;kBeep("chest");kLine("You rule Mars! Victory!",4);if(k.emp.wins===1)kTrophy("emp1","👑","Emperor of Mars!","Won a game of Mars Empire against Robo.")}else kLine("Robo wins this time. Rematch!",4);persist()}
function meView(v){const E=KV.E,k=KS(),me=E.p[0],bot=E.p[1];
  if(E.stage==="q"&&!E.over){v.innerHTML=`<div class="kids">${kToastHtml()}${kTop("Mars Empire","col")}<div class="kcard"><b>${{card:"📡 Mission Card: answer to win a bonus!",lab:"🔬 Research Lab: answer to discover new tech!",storm:"🌪️ Dust Storm: answer to avoid damage!"}[E.qkind]}</b></div>${kQuestion(E.Q,E.ans,"meq")}</div>`;return}
  const pos=[[0,0],[0,1],[0,2],[0,3],[0,4],[1,4],[2,4],[3,4],[4,4],[4,3],[4,2],[4,1],[4,0],[3,0],[2,0],[1,0]];
  const cells=KMB.map((s,i)=>{const o=E.own[i],own=o&&o.o!==null?(o.o===0?"me":"bot"):"",tok=E.p.map((p,pi)=>p.pos===i?p.ic:"").join("");return `<div class="mbc ${own}" style="grid-row:${pos[i][0]+1};grid-column:${pos[i][1]+1}"><span>${s[1]}</span><b>${esc(s[2])}</b>${s[0]==="reg"?`<em>${o.o===null?`${s[3]} 💠`:KMBUILD[o.b]?KMBUILD[o.b].slice(0,2):"rent "+meRent(E,i)}</em>`:""}${tok?`<i class="mtok">${tok}</i>`:""}</div>`}).join("");
  const cur=KMB[me.pos],ctrl=E.over?`<div class="kh">${E.win==="me"?"👑 You win!":E.win==="bot"?"🤖 Robo wins!":"🤝 Tie!"}</div><div class="ksmall">Your worth ${E.wa} 💠 vs Robo ${E.wb} 💠 (cash + land + buildings) · +${E.win==="me"?2:1} 🎟️</div><button class="kbtn big green" data-k="emp">New game 🎲</button>`
   :E.stage==="buy"?`<div class="kh">${cur[1]} ${esc(cur[2])} is free!</div><div class="ksmall">Price ${cur[3]} 💠 · rent ${cur[4]} 💠 (×3 with an outpost, ×7 base, ×15 city)</div><div class="kpad"><button class="kbtn green" data-me="buy" ${me.cash<cur[3]?"disabled":""}>Buy ${cur[3]} 💠</button><button class="kbtn ghost" data-me="skip">Skip</button></div>`
   :E.stage==="build"?`<div class="kh">Your land: ${esc(cur[2])}</div><div class="ksmall">Build a ${KMBUILD[E.own[me.pos].b+1].slice(3)} for ${Math.round(cur[3]*.6)} 💠? Rent goes from ${meRent(E,me.pos)} to ${Math.round(cur[4]*KMBMUL[E.own[me.pos].b+1]*(1+me.tech*.1))} 💠.</div><div class="kpad"><button class="kbtn green" data-me="build" ${me.cash<Math.round(cur[3]*.6)?"disabled":""}>Build</button><button class="kbtn ghost" data-me="skip">Not now</button></div>`
   :`<button class="kbtn big mroll" data-me="roll">🎲 Roll the dice</button>${E.die?`<div class="mdie">${["","⚀","⚁","⚂","⚃","⚄","⚅"][E.die]}</div>`:""}`;
  v.innerHTML=`<div class="kids">${kToastHtml()}${kTop("Mars Empire","col")}<div class="mboard">${cells}<div class="mcenter"><div class="mscore"><span>🧑‍🚀 ${me.cash} 💠 · 🔬${me.tech}</span><span>🤖 ${bot.cash} 💠 · 🔬${bot.tech}</span></div><div class="ksmall">Round ${E.round}/${E.maxR}</div>${ctrl}<div class="mtip">💡 ${esc(KMTIP[E.round%KMTIP.length])}</div></div></div>
   <div class="kcard pklog">${E.log.slice(-4).map(l=>`<div>${esc(l)}</div>`).join("")}</div>
   <details class="kcard"><summary class="kh">📘 How to play (easy!)</summary><p>Roll the dice and move your rover. Land on a free region? <b>Buy it</b>. When Robo lands on your land, Robo pays you <b>rent</b>. Land on your own region to <b>build</b>: 🏕️ outpost (×3 rent), 🏠 base (×7), 🏙️ city (×15). 🔬 Labs give <b>tech</b> (+10% rent each). 📡 Mission cards and 🌪️ storms ask a question. Pass the 🚀 Launch Pad for +100 💠. After ${E.maxR} rounds, the richest empire wins!</p></details></div>`}

/* Brain Gates: every 15 seconds three answer boards cross the road; drive through the right one for turbo */
function kGateStep(D,dt,lx,carY,SP){if(SP||D.over)return;D.gT=(D.gT==null?12:D.gT)-dt;if(!D.gate&&D.gT<=0){D.gT=20;const k=KS(),P=kFact(Math.max(1,k.lv.math)),opts=kShuf([P.a,...P.o.filter(x=>x!==P.a).slice(0,2)]);D.gate={q:P.q,a:P.a,opts,y:-90};D.obs=D.obs.filter(o=>o.y>-20||o.y<-200);kBeep("chime");kLine("Brain gate! "+String(P.q).replace("×","times").replace("÷","divided by").replace("−","minus")+"?",2)}
  if(!D.gate)return;D.gate.y+=D.v*dt;if(D.gate.y>=carY-10&&!D.gate.done){D.gate.done=1;const pick=D.gate.opts[D.lane],ok=pick===D.gate.a;kAnswer("math",ok,{s:"math",q:D.gate.q,o:[],a:-1,nosave:1,rm:D.gate.hinted?[0]:null});
    if(ok&&D.gate.hinted){D.plaid=Math.max(D.plaid,2);D.tip="✅ Right! (hint used, so no bonus ⚡)";D.tipT=2.5;kBeep("ok")}else if(ok){D.bolts+=5;D.plaid=Math.max(D.plaid,2);D.gates=(D.gates||0)+1;kBeep("kaching");kLine("Correct! Turbo!",2);D.fx=(D.fx||[]).concat([{x:lx(D.lane),y:carY-40,t:0,k:"spark",txt:"+5 ⚡ TURBO"}])}else{kBeep("no");D.gateMsg=`${D.gate.q} = ${D.gate.a}`;D.gateMsgT=2.5}}
  if(D.gate.y>carY+120)D.gate=null;D.gateMsgT=Math.max(0,(D.gateMsgT||0)-dt)}
function kGateDraw(c,D,lx,LW,W){const G=D.gate;c.fillStyle="rgba(5,8,24,.85)";c.fillRect(0,G.y-64,W,26);c.fillStyle="#ffd23f";c.font="900 15px system-ui";c.textAlign="center";c.fillText(`🧠 ${G.q} = ?`,W/2,G.y-51);
  G.opts.forEach((v,i)=>{const x=lx(i);c.fillStyle=G.done?(v===G.a?"#2ec27e":"#6b7280"):G.hinted&&v===G.a?"#2ec27e":"#3fb6ff";c.beginPath();c.roundRect(x-LW/2+5,G.y-32,LW-10,34,8);c.fill();c.fillStyle="#fff";c.font="900 18px system-ui";c.fillText(v,x,G.y-14)})}

/* Kids button on the adult home: hand the separate Kids app to a child instead of opening it inside the adult app */
function kidsGive(){const U="https://study.solvinglifewith.com/kids/";let o=document.getElementById("kgive");if(o)o.remove();
  o=document.createElement("div");o.id="kgive";o.style.cssText="position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.55);display:flex;align-items:center;justify-content:center;padding:16px";
  o.innerHTML=`<div style="background:#fff;color:#111;border-radius:18px;max-width:420px;width:100%;padding:18px;font:15px/1.45 system-ui,sans-serif;max-height:90vh;overflow:auto">
  <div style="font:900 20px system-ui">🚀 Becoming Genius · Kids app</div>
  <p style="margin:8px 0"><b>Give this app to your kids and let them test it!</b> Free learning games: math, reading, space, flying, chess and more. It is its own separate app, so your exam progress stays yours.</p>
  <p style="margin:8px 0;word-break:break-all"><b>Kids link:</b> <a href="${U}" target="_blank" rel="noopener">${U}</a></p>
  <div style="display:flex;gap:8px;flex-wrap:wrap;margin:10px 0">
   <button type="button" id="kgshare" style="flex:1;padding:12px;border:0;border-radius:12px;background:#d10000;color:#fff;font-weight:800">Send link</button>
   <button type="button" id="kgcopy" style="flex:1;padding:12px;border:0;border-radius:12px;background:#1e3a8a;color:#fff;font-weight:800">Copy link</button></div>
  <div style="font-weight:800;margin-top:6px">Install it on your kid's phone or tablet</div>
  <ul style="margin:6px 0 10px 18px;padding:0">
   <li><b>iPhone/iPad:</b> open the link in Safari → Share → Add to Home Screen → Add.</li>
   <li><b>Android:</b> open it in Chrome → ⋮ → Install app (or Add to Home screen).</li>
   <li>Opened inside Messenger or Facebook? Tap ••• → Open in Safari/Chrome first.</li></ul>
  <div style="display:flex;gap:8px"><a href="${U}" target="_blank" rel="noopener" style="flex:1;text-align:center;padding:12px;border-radius:12px;background:#eef;color:#1e3a8a;font-weight:800;text-decoration:none">Try it here</a>
   <button type="button" id="kgclose" style="flex:1;padding:12px;border:0;border-radius:12px;background:#ddd;font-weight:800">Close</button></div></div>`;
  document.body.appendChild(o);
  o.addEventListener("click",e=>{if(e.target===o||e.target.id==="kgclose")o.remove()});
  const msg="Free learning games for kids from Solving Life LLC: "+U;
  o.querySelector("#kgshare").onclick=()=>{if(navigator.share)navigator.share({title:"Becoming Genius",text:"Free learning games for kids",url:U}).catch(()=>{});else location.href="sms:?&body="+encodeURIComponent(msg)};
  o.querySelector("#kgcopy").onclick=e=>{try{navigator.clipboard.writeText(U);e.target.textContent="Copied ✓"}catch(_){prompt("Copy this link:",U)}};}
